// Regenerates backend/src/abi.ts from the compiled StreetSyncEscrow artifact so the
// backend never decodes events with a stale, hand-written ABI.
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..", "..");
const artifact = JSON.parse(readFileSync(join(root, "contracts/artifacts/src/StreetSyncEscrow.sol/StreetSyncEscrow.json"), "utf8"));
const out = `/**
 * abi.ts — GENERATED by contracts/scripts/export-abi.mjs from the compiled
 * StreetSyncEscrow artifact. Do not edit by hand; run \`npm run abi:sync\`.
 */

export const ESCROW_ABI = ${JSON.stringify(artifact.abi, null, 2)} as const;
`;
writeFileSync(join(root, "backend/src/abi.ts"), out);
console.log(`Wrote backend/src/abi.ts (${artifact.abi.length} ABI entries)`);
